root = os.path.dirname(os.path.abspath(__file__))
if not (os.path.isdir(os.path.join(root, "backend")) and os.path.exists(os.path.join(root, "app.py"))):
    print("\n  This file must sit in your citypulse-jaipur folder (next to app.py and the backend folder).")
    print("  Move it there and run it again.\n")
    sys.exit(1)

backup = os.path.join(root, ".update_backup")
print("\n  Updating CityPulse Jaipur (update 3)...\n")
for rel, b64 in FILES.items():
    path = os.path.join(root, rel)
    new = base64.b64decode(b64)
    old = open(path, "rb").read() if os.path.exists(path) else None
    if old == new:
        continue
    if old is not None:
        dest = os.path.join(backup, rel)
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        shutil.copy2(path, dest)
    os.makedirs(os.path.dirname(path) or root, exist_ok=True)
    with open(path, "wb") as f:
        f.write(new)
    print(f"    {'updated' if old is not None else 'added  '}    {rel}")

env = os.path.join(root, ".env")
if not os.path.exists(env):
    shutil.copy2(os.path.join(root, ".env.example"), env)
    print("    added      .env   (paste your API keys in here)")
gi = os.path.join(root, ".gitignore")
if ".update_backup/" not in open(gi).read():
    with open(gi, "a") as f:
        f.write("\n.update_backup/\n")

print("\n  Installing new libraries (folium, streamlit-folium)...")
res = subprocess.run([sys.executable, "-m", "pip", "install", "-q", "-r", os.path.join(root, "requirements.txt")])
if res.returncode != 0:
    print("  Couldn't install automatically. Run this yourself:")
    print("      python3 -m pip install -r requirements.txt")
else:
    print("  Libraries installed.")
print("\n  Done. Old versions of changed files are saved in .update_backup")
print("  Now run:  python3 run.py\n")
try:
    os.remove(os.path.abspath(__file__))
except OSError:
    pass
